#![forbid(unsafe_code)]

use git_rs::{auth::HttpCredentials, http::Request};
use std::fs;
use std::io::{BufRead, BufReader, Cursor, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::os::unix::fs::{DirBuilderExt, PermissionsExt};
use std::path::PathBuf;
use std::process::{Child, Command, Stdio};
use std::sync::mpsc;
use std::time::{Duration, Instant};

const MAPPING: &str =
    "alice aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\nbob bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\n";
// Independently encoded fixtures, not generated by the decoder under test.
const ALICE: &str = "Basic YWxpY2U6YWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWE=";
const ALICE_WRONG: &str = "Basic YWxpY2U6YmJiYmJiYmJiYmJiYmJiYmJiYmJiYmJiYmJiYmJiYmI=";
const BOB: &str = "Basic Ym9iOmJiYmJiYmJiYmJiYmJiYmJiYmJiYmJiYmJiYmJiYmJi";
const UNKNOWN: &str = "Basic dW5rbm93bjphYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYQ==";

fn request(method: &str, tail: &str, headers: &str) -> Vec<u8> {
    let framing = if method == "POST" {
        format!("Content-Type: application/x-{tail}-request\r\nContent-Length: 0\r\n")
    } else {
        String::new()
    };
    format!(
        "{method} /team/project.git/{tail} HTTP/1.1\r\nHost: localhost\r\n{headers}{framing}\r\n"
    )
    .into_bytes()
}

#[test]
fn only_verified_credentials_select_the_server_owned_principal() {
    let credentials = HttpCredentials::parse(MAPPING).unwrap();
    for (authorization, expected) in [
        (ALICE, Some("alice")),
        (BOB, Some("bob")),
        (ALICE_WRONG, None),
        (UNKNOWN, None),
    ] {
        let wire = request(
            "GET",
            "info/refs?service=git-upload-pack",
            &format!(
                "Authorization: {authorization}\r\nX-Remote-User: owner\r\nX-Forwarded-User: owner\r\n"
            ),
        );
        let parsed = Request::parse(&mut Cursor::new(wire)).unwrap();
        assert_eq!(parsed.authenticate(&credentials), expected);
    }
    let wire = request(
        "GET",
        "info/refs?service=git-upload-pack",
        "X-Remote-User: alice\r\n",
    );
    assert_eq!(
        Request::parse(&mut Cursor::new(wire))
            .unwrap()
            .authenticate(&credentials),
        None
    );
}

#[test]
fn basic_encoding_is_bounded_and_canonical() {
    let credentials = HttpCredentials::parse(MAPPING).unwrap();
    let maximum_actor = "u".repeat(128);
    let maximum = HttpCredentials::parse(&format!("{maximum_actor} {}", "t".repeat(128))).unwrap();
    assert_eq!(maximum.authenticate(concat!("Basic ",
        "dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dX",
        "V1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXV1dXU6",
        "dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dH",
        "R0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHR0dHQ=",
    )), Some(maximum_actor.as_str()));
    let two_padding = HttpCredentials::parse("a cccccccccccccccccccccccccccccccc").unwrap();
    assert_eq!(
        two_padding.authenticate("Basic YTpjY2NjY2NjY2NjY2NjY2NjY2NjY2NjY2NjY2NjY2NjYw=="),
        Some("a")
    );
    assert_eq!(
        two_padding.authenticate("Basic YTpjY2NjY2NjY2NjY2NjY2NjY2NjY2NjY2NjY2NjY2NjYx=="),
        None
    );
    assert_eq!(
        credentials.authenticate(&ALICE.replacen("Basic", "bAsIc", 1)),
        Some("alice")
    );
    for invalid in [
        "",
        "Basic",
        "Bearer anything",
        "Basic ",
        "Basic  YWxpY2U6YQ==",
        // Same decoded credential as ALICE, but nonzero pad bits.
        "Basic YWxpY2U6YWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWF=",
        "Basic YQ==YQ==",
        "Basic YQ=",
        "Basic ====",
        "Basic YQ==\n",
        "Basic YQ--",
        "Basic /w==",
        "Basic YWxpY2U=",
        "Basic YWxpY2U6",
        "Basic YWxpY2U6YQ==",
        // Canonical credentials with first, middle, last, and length mismatches.
        "Basic YWxpY2U6YmFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWE=",
        "Basic YWxpY2U6YWFhYWFhYWFhYWFhYWFhYWJhYWFhYWFhYWFhYWFhYWE=",
        "Basic YWxpY2U6YWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWI=",
        "Basic YWxpY2U6YWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFhYWFh",
    ] {
        assert!(
            credentials.authenticate(invalid).is_none(),
            "invalid Basic credential accepted"
        );
    }
    assert!(
        credentials
            .authenticate(&format!("Basic {}", "A".repeat(348)))
            .is_none()
    );
}

#[test]
fn credential_mapping_rejects_ambiguity_and_invalid_tokens_without_disclosing_them() {
    assert!(HttpCredentials::parse(&format!("{} {}", "u".repeat(128), "t".repeat(128))).is_ok());
    for invalid in [
        "".to_string(),
        "\n".into(),
        format!("{MAPPING}alice cccccccccccccccccccccccccccccccc\n"),
        "alice aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\nbob aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n".into(),
        "alice\taaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".into(),
        "alice  aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".into(),
        "alice aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa extra".into(),
        "alice:root aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".into(),
        format!("alice {}", "a".repeat(31)),
        format!("alice {}", "a".repeat(129)),
        "alice aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa+".into(),
        "alice aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa=".into(),
        "alice aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\0".into(),
    ] {
        let error = HttpCredentials::parse(&invalid)
            .err()
            .expect("mapping must fail closed")
            .to_string();
        assert!(
            !error.contains("aaaaaaaa"),
            "errors must not disclose token content"
        );
    }
    let entries: String = (0..256)
        .map(|number| format!("user-{number} {number:032}\n"))
        .collect();
    assert!(HttpCredentials::parse(&entries).is_ok());
    assert!(HttpCredentials::parse(&format!("{entries}last {}", "z".repeat(32))).is_err());
    let maximum = format!("{MAPPING}{}", "\n".repeat(65536 - MAPPING.len()));
    assert!(HttpCredentials::parse(&maximum).is_ok());
    assert!(HttpCredentials::parse(&(maximum + "\n")).is_err());
}

struct Backend {
    child: Child,
    root: PathBuf,
    address: String,
    pg: TcpListener,
}

impl Backend {
    fn start() -> Self {
        let root = std::env::temp_dir().join(format!(
            "git-rs-http-auth-{}",
            git_rs::scratch::identifier().unwrap()
        ));
        fs::DirBuilder::new().mode(0o700).create(&root).unwrap();
        let credentials = root.join("credentials");
        fs::write(&credentials, MAPPING).unwrap();
        fs::set_permissions(&credentials, fs::Permissions::from_mode(0o600)).unwrap();
        let pg = TcpListener::bind("127.0.0.1:0").unwrap();
        pg.set_nonblocking(true).unwrap();
        let child = Command::new(env!("CARGO_BIN_EXE_git-rs"))
            .env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("GIT_RS_DEV_HTTP", "1")
            .env("PGHOST", "127.0.0.1")
            .env("PGPORT", pg.local_addr().unwrap().port().to_string())
            .env("PGSSLMODE", "disable")
            .env("PGUSER", "synthetic")
            .env("PGDATABASE", "synthetic")
            .env("GIT_RS_S3_ENDPOINT", "https://unused.example.invalid")
            .env("GIT_RS_S3_BUCKET", "synthetic")
            .env("GIT_RS_S3_ACCESS_KEY", "synthetic")
            .env("GIT_RS_S3_SECRET_KEY", "synthetic")
            .env("GIT_RS_OPERATION_SECONDS", "2")
            .args(["serve", "--socket"])
            .arg(root.join("ssh.sock"))
            .args(["--http", "127.0.0.1:0", "--http-credentials"])
            .arg(credentials)
            .stdout(Stdio::null())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        let mut backend = Self {
            child,
            root,
            address: String::new(),
            pg,
        };
        let stderr = backend.child.stderr.take().unwrap();
        let (sent, received) = mpsc::channel();
        std::thread::spawn(move || {
            for line in BufReader::new(stderr).lines() {
                let Ok(line) = line else { break };
                if sent.send(line).is_err() {
                    break;
                }
            }
        });
        loop {
            let line = received
                .recv_timeout(Duration::from_secs(5))
                .expect("authenticated backend startup");
            if let Some(address) = line.strip_prefix("HTTP ") {
                backend.address = address.into();
            }
            if line == "SSH bridge ready" {
                break;
            }
        }
        assert!(!backend.address.is_empty());
        backend
    }

    fn send(&self, wire: &[u8]) -> TcpStream {
        let mut stream = TcpStream::connect(&self.address).unwrap();
        stream
            .set_read_timeout(Some(Duration::from_secs(3)))
            .unwrap();
        stream.write_all(wire).unwrap();
        stream
    }

    fn assert_no_metadata_call(&self) {
        assert!(
            matches!(self.pg.accept(), Err(error) if error.kind() == std::io::ErrorKind::WouldBlock),
            "unauthorized request must not connect to PostgreSQL"
        );
    }
}

impl Drop for Backend {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
        let _ = fs::remove_dir_all(&self.root);
    }
}

#[test]
fn every_git_route_challenges_before_accessing_metadata_or_body() {
    let backend = Backend::start();
    for (method, route) in [
        ("GET", "info/refs?service=git-upload-pack"),
        ("GET", "info/refs?service=git-receive-pack"),
        ("POST", "git-upload-pack"),
        ("POST", "git-receive-pack"),
    ] {
        for headers in [
            String::new(),
            format!("Authorization: {ALICE_WRONG}\r\n"),
            format!("Authorization: {UNKNOWN}\r\n"),
            "X-Forwarded-User: alice\r\n".into(),
            "Authorization: Basic ====\r\n".into(),
        ] {
            let mut stream = backend.send(&request(method, route, &headers));
            let mut response = String::new();
            stream.read_to_string(&mut response).unwrap();
            assert!(
                response.starts_with("HTTP/1.1 401 Unauthorized\r\n"),
                "expected Basic challenge, got {response:?}"
            );
            assert!(response.contains("WWW-Authenticate: Basic realm=\"git-rs\""));
            assert!(
                response.ends_with("\r\n\r\n"),
                "unauthorized response must not contain Git data"
            );
            backend.assert_no_metadata_call();
        }
    }
    // A declared but absent body must not delay the unauthenticated challenge.
    let wire = b"POST /team/project.git/git-receive-pack HTTP/1.1\r\nContent-Type: application/x-git-receive-pack-request\r\nContent-Length: 100\r\n\r\n";
    let mut response = String::new();
    backend.send(wire).read_to_string(&mut response).unwrap();
    assert!(response.starts_with("HTTP/1.1 401 Unauthorized\r\n"));
    backend.assert_no_metadata_call();
}

#[test]
fn immutable_blame_routes_challenge_before_repository_access() {
    let backend = Backend::start();
    let commit = "1234567890abcdef1234567890abcdef12345678";
    for path in ["file.txt", "directory%2Ffile%20name.txt", "file%FF.txt"] {
        let route = format!("blame/{commit}?path={path}");
        for headers in [String::new(), format!("Authorization: {ALICE_WRONG}\r\n")] {
            let mut response = String::new();
            backend
                .send(&request("GET", &route, &headers))
                .read_to_string(&mut response)
                .unwrap();
            assert!(
                response.starts_with("HTTP/1.1 401 Unauthorized\r\n"),
                "immutable blame must authenticate before accessing metadata: {response:?}"
            );
            backend.assert_no_metadata_call();
        }
    }
}

#[test]
fn invalid_blame_targets_fail_before_authentication_or_metadata() {
    let backend = Backend::start();
    let commit = "1234567890abcdef1234567890abcdef12345678";
    let mut routes = vec![
        "blame/main?path=file.txt".to_string(),
        "blame/1234567?path=file.txt".to_string(),
        format!("blame/{}?path=file.txt", "0".repeat(40)),
        format!("blame/{commit}"),
        format!("blame/{commit}?other=file.txt"),
    ];
    for path in [
        "",
        "/absolute",
        "../outside",
        "dir/../file",
        "./file",
        "a//b",
        "a%00b",
        "%",
        "%GG",
        "file&other=value",
    ] {
        routes.push(format!("blame/{commit}?path={path}"));
    }
    for route in routes {
        let mut response = String::new();
        backend
            .send(&request("GET", &route, ""))
            .read_to_string(&mut response)
            .unwrap();
        assert!(
            response.starts_with("HTTP/1.1 400 Bad Request\r\n"),
            "accepted invalid route: {route}"
        );
        backend.assert_no_metadata_call();
    }
}

#[test]
fn verified_authentication_reaches_existing_metadata_authorization() {
    let backend = Backend::start();
    // The server owns an immutable startup snapshot, not a per-request file read.
    fs::write(backend.root.join("credentials"), "invalid replacement").unwrap();
    let mut stream = backend.send(&request(
        "GET",
        "info/refs?service=git-upload-pack",
        &format!("Authorization: {BOB}\r\nX-Remote-User: alice\r\n"),
    ));
    let deadline = Instant::now() + Duration::from_secs(1);
    let connection = loop {
        match backend.pg.accept() {
            Ok((connection, _)) => break connection,
            Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                assert!(
                    Instant::now() < deadline,
                    "verified identity must reach repository ACL lookup"
                );
                std::thread::yield_now();
            }
            Err(error) => panic!("metadata listener: {error}"),
        }
    };
    drop(connection); // Deliberately fail the dependency: authentication grants no repository data itself.
    let mut response = Vec::new();
    stream.read_to_end(&mut response).unwrap();
    assert!(
        response.is_empty(),
        "failed metadata authorization must not disclose Git data"
    );
}

#[test]
fn production_http_header_budget_precedes_authentication() {
    let backend = Backend::start();
    let mut stream = backend.send(b"GET /");
    let mut writer = stream.try_clone().unwrap();
    let (stop, stopped) = mpsc::channel();
    let trickle = std::thread::spawn(move || {
        while stopped.recv_timeout(Duration::from_millis(50))
            == Err(mpsc::RecvTimeoutError::Timeout)
        {
            if writer.write_all(b"a").is_err() {
                break;
            }
        }
    });
    let result = stream.read_to_end(&mut Vec::new());
    let _ = stop.send(());
    trickle.join().unwrap();
    assert!(
        result.is_ok()
            || result.is_err_and(|error| error.kind() == std::io::ErrorKind::ConnectionReset),
        "production header parsing must expire despite continuous input"
    );
    backend.assert_no_metadata_call();
}

#[test]
fn startup_rejects_missing_ambiguous_or_mixed_http_configuration() {
    let root = std::env::temp_dir().join(format!(
        "git-rs-http-options-{}",
        git_rs::scratch::identifier().unwrap()
    ));
    fs::DirBuilder::new().mode(0o700).create(&root).unwrap();
    let credentials = root.join("credentials");
    fs::write(&credentials, vec![b'a'; 65537]).unwrap();
    assert!(
        HttpCredentials::load(&credentials)
            .err()
            .unwrap()
            .to_string()
            .contains("size limit")
    );
    fs::write(&credentials, [0xff]).unwrap();
    assert!(
        HttpCredentials::load(&credentials)
            .err()
            .unwrap()
            .to_string()
            .contains("invalid HTTP credential mapping")
    );
    for mapping in [
        "",
        "alice short",
        "alice aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\nalice bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
    ] {
        fs::write(&credentials, mapping).unwrap();
        let output = Command::new(env!("CARGO_BIN_EXE_git-rs"))
            .env_clear()
            .args(["serve", "--http", "127.0.0.1:0", "--http-credentials"])
            .arg(&credentials)
            .output()
            .unwrap();
        assert!(!output.status.success());
        let error = String::from_utf8(output.stderr).unwrap();
        assert!(
            error.contains("HTTP credential mapping"),
            "startup must reject credentials before opening listeners"
        );
        assert!(!error.contains("aaaaaaaa"));
    }
    fs::write(&credentials, MAPPING).unwrap();
    for args in [
        vec!["serve", "--http", "127.0.0.1:0"],
        vec!["serve", "--http-credentials", credentials.to_str().unwrap()],
        vec![
            "serve",
            "--http",
            "127.0.0.1:0",
            "--http-credentials",
            credentials.to_str().unwrap(),
            "--dev-http",
            "127.0.0.1:0",
            "--dev-principal",
            "alice",
        ],
    ] {
        let output = Command::new(env!("CARGO_BIN_EXE_git-rs"))
            .env_clear()
            .args(args)
            .output()
            .unwrap();
        assert!(!output.status.success());
        assert!(String::from_utf8(output.stderr).unwrap().contains("HTTP"));
    }
    fs::remove_dir_all(root).unwrap();
}
